import sys

def main():
    import sys
    import collections

    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    degree = [0] * n
    edges = collections.defaultdict(list)
    for i in range(n):
        degree[i] = a[i]

    stack = []
    for i in range(n):
        if degree[i] == 0:
            stack.append(i)

    order = []
    while stack:
        u = stack.pop()
        order.append(u)
        for v in edges[u]:
            degree[v] -= 1
            if degree[v] == 0:
                stack.append(v)

    if len(order) != n:
        print("Impossible")
        return

    used = [False] * n
    for u in order:
        used[u] = True

    for i in range(n):
        if not used[i]:
            order.append(i)

    for i in range(n):
        for j in range(i + 1, n):
            if a[order[i]] > 0 and a[order[j]] > 0 and order[i] not in edges[order[j]]:
                edges[order[i]].append(order[j])
                edges[order[j]].append(order[i])
                a[order[i]] -= 1
                a[order[j]] -= 1

    for i in range(n):
        if a[order[i]] != 0:
            print("Impossible")
            return

    print("Possible")
    print(" ".join(str(x + 1) for x in order))

main()
